	('television.titol', 'television', 'text', null, 0, 'Television e video', 'Télévision et vidéo', 'Televisión y vídeo', 'Television and video', 'Televisió i vídeo', null, null, true),
	('television.frasa', 'television', 'text', null, 0, 'Las cadenas, las emissions e las videos en occitan.', 'Les chaînes, les émissions et les vidéos en occitan.', 'Los canales, los programas y los vídeos en occitano.', 'The channels, the programmes and the videos in Occitan.', 'Els canals, els programes i els vídeos en occità.', null, null, true),
	('parcors.titol', 'parcors', 'text', null, 0, 'Lo parcors', 'Le parcours', 'El recorrido', 'The learning path', 'El recorregut', null, null, true),
	('parcors.nota', 'parcors', 'text', null, 0, 'Sens compte, ta progression demòra dins aqueste navigator. Un compte gratuit la garda sus totes tos aparelhs.', 'Sans compte, ta progression reste dans ce navigateur. Un compte gratuit la garde sur tous tes appareils.', 'Sin cuenta, tu progreso se queda en este navegador. Una cuenta gratuita lo guarda en todos tus dispositivos.', 'Without an account, your progress stays in this browser. A free account keeps it on all your devices.', 'Sense compte, el teu progrés es queda en aquest navegador. Un compte gratuït el guarda a tots els teus dispositius.', null, null, true),
